GEN = {'ar':'ar','cs':'cs','de':'de','en':'en','es':'es','fr':'fr','hi':'hi','hu':'hu','id':'id','it':'it','ja':'ja',
       'ko':'ko','pl':'pl','pt':'pt','ro':'ro','ru':'ru','th':'th','tr':'tr','uk':'uk','ur':'ur','vi':'vi','zh':'zh'}


def rd(p):
    raw = open(p, 'rb').read().decode('utf-8')
    return raw, ('\r\n' in raw)


def wr(p, text, crlf):
    if crlf:
        text = text.replace('\r\n', '\n').replace('\n', '\r\n')
    open(p, 'wb').write(text.encode('utf-8'))


def dq(s):
    return "'" + s.replace('\\', '\\\\').replace("'", "\\'").replace('$', '\\$') + "'"


def gaps(s):
    return (s.count('(') - s.count(')'), s.count('{') - s.count('}'), s.count('[') - s.count(']'))


def main():
    out = {}
    ok = True
    # 이미 적용?
    if os.path.exists(HELP) and 'helpGuideHeader' in open(HELP, encoding='utf-8').read():
        print('이미 적용돼 있어요')
        return
    # 1) 설정 도움말 화면
    if not os.path.exists(HELP):
        print('❌ 파일이 없어요:', HELP); sys.exit(1)
    raw, crlf = rd(HELP)
    t = raw.replace('\r\n', '\n')
    before = gaps(t)
    for i, (old, new) in enumerate(SETTINGS_EDITS, 1):
        n = t.count(old)
        if n != 1:
            print('❌ settings_help_screen.dart %d번째 곳을 못 찾았어요 (%d개)' % (i, n)); ok = False; continue
        t = t.replace(old, new)
        print('✔ settings_help_screen.dart %d번째 곳' % i)
    if gaps(t) != before:
        print('❌ settings_help_screen.dart 괄호가 안 맞아요'); ok = False
    out[HELP] = (t, crlf)
    # 2) 번역 파일 23개 (맨 끝에 새 글자)
    for lang, d in TR.items():
        p = os.path.join(L10N, 'app_%s.arb' % lang)
        if not os.path.exists(p):
            print('❌ 파일이 없어요:', p); ok = False; continue
        raw, crlf = rd(p)
        t = raw.replace('\r\n', '\n')
        try:
            j = json.loads(t)
        except Exception as e:
            print('❌ %s 읽기 오류: %s' % (p, e)); ok = False; continue
        if any(k in j for k in KEYS):
            print('❌ %s 에 이미 같은 이름이 있어요' % p); ok = False; continue
        end = t.rstrip().rfind('}')
        head = t[:end].rstrip()
        add = ''.join(',\n  %s: %s' % (json.dumps(k), json.dumps(d[k], ensure_ascii=False)) for k in KEYS)
        t2 = head + add + '\n}\n'
        try:
            j2 = json.loads(t2)
            assert all(j2[k] == d[k] for k in KEYS) and len(j2) == len(j) + len(KEYS)
        except Exception as e:
            print('❌ %s 고친 뒤 확인 실패: %s' % (p, e)); ok = False; continue
        out[p] = (t2, crlf)
        print('✔ app_%s.arb' % lang)
    # 3) 만들어진 글자 파일 (flutter가 다시 만들어도 같은 내용 — 바로 돌릴 수 있게)
    p = os.path.join(L10N, 'app_localizations.dart')
    if os.path.exists(p):
        raw, crlf = rd(p)
        t = raw.replace('\r\n', '\n')
        anchor = '  String get langNameUr;\n'
        if t.count(anchor) != 1:
            print('❌ app_localizations.dart 자리를 못 찾았어요'); ok = False
        else:
            add = ''.join('\n  /// No description provided for @%s.\n  ///\n  /// In ko, this message translates to:\n  /// **%s**\n  String get %s;\n'
                          % (k, dq(TR['ko'][k]), k) for k in KEYS)
            out[p] = (t.replace(anchor, anchor + add), crlf)
            print('✔ app_localizations.dart')
    for lang, g in GEN.items():
        p = os.path.join(L10N, 'app_localizations_%s.dart' % g)
        if not os.path.exists(p):
            print('❌ 파일이 없어요:', p); ok = False; continue
        raw, crlf = rd(p)
        t = raw.replace('\r\n', '\n')
        lines = t.split('\n')
        idx = [i for i, l in enumerate(lines) if l.startswith('  String get langNameUr =>')]
        want = 2 if g == 'zh' else 1
        if len(idx) != want:
            print('❌ app_localizations_%s.dart 자리를 못 찾았어요' % g); ok = False; continue
        langs = ['zh', 'zh_Hant'] if g == 'zh' else [lang]
        for i, L in reversed(list(zip(idx, langs))):
            j = i
            while not lines[j].rstrip().endswith(';'):
                j += 1
            add = []
            for k in KEYS:
                add += ['', '  @override', '  String get %s => %s;' % (k, dq(TR[L][k]))]
            lines[j + 1:j + 1] = add
        out[p] = ('\n'.join(lines), crlf)
        print('✔ app_localizations_%s.dart' % g)
    if not ok:
        print('\n❌ 하나라도 실패해서 아무것도 저장 안 했어요'); sys.exit(1)
    for p, (t, crlf) in out.items():
        wr(p, t, crlf)
    print('\n✔ 다 됐어요 (%d개 파일)' % len(out))


main()
